var ES_SYSTEM_REQUIRED = 1;
var ES_DISPLAY_REQUIRED = 2;
var FLAGS = (ES_CONTINUOUS | ES_SYSTEM_REQUIRED | ES_DISPLAY_REQUIRED) >>> 0;
