async function statusReport(missionId) {
  const m = missionId !== void 0 ? getMission(missionId) : getActiveMission() ?? getLastMission();
  if (!m) return "No hay ninguna misi\xF3n. Crea una con /dementeking:trading.";
  const v = await valuation(m.id);
  const current = m.status === "active" ? v.totalUsd : m.final_usd ?? v.totalUsd;
  const change = (current - m.initial_usd) / m.initial_usd * 100;
  const progress = (current - m.initial_usd) / (m.target_usd - m.initial_usd) * 100;
  const statusText = m.status === "active" ? `en curso, quedan ${timeLeft(m.deadline)}` : m.status === "succeeded" ? "CONSEGUIDA" : m.status === "expired" ? "terminada sin llegar al objetivo" : m.status === "bust" ? "SIN FONDOS: se qued\xF3 sin dinero para operar" : "detenida por el usuario";
  const lines = [];
  lines.push(`Misi\xF3n #${m.id}: ${statusText}`);
  lines.push(`Valor: ${usd(current)} (${pct3(change)}) \xB7 objetivo ${usd(m.target_usd)} \xB7 progreso ${Math.round(progress)} %`);
  lines.push(m.instructions ? `Instrucciones: ${m.instructions}` : "Modo libre");
  const open2 = listPositions(m.id).filter((p) => p.status === "open");
  if (m.status === "active") {
    const cash = v.holdings.filter((h) => ["USDC", "USDT"].includes(h.symbol)).reduce((s, h) => s + h.usd, 0);
    lines.push("", `Posiciones (${open2.length}) \xB7 liquidez ${usd(cash)}`);
    for (const p of open2) {
      const h = v.holdings.find((x) => x.venue === p.venue && x.asset === p.asset);
      const share = h && h.amount > 0 ? Math.min(1, p.qtyOpen / h.amount) : 0;
      const now2 = (h?.usd ?? 0) * share;
      const cost = p.openCostUsd;
      lines.push(`- ${p.symbol}: ${usd(now2)} (${pct3(cost ? (now2 - cost) / cost * 100 : 0)} sobre ${usd(cost)})`);
    }
    const orders = listOrders(m.id, "open");
    if (orders.length) {
      lines.push(`\xD3rdenes abiertas: ${orders.map((o) => o.condition === "time" ? `#${o.id} a las ${hhmm3(o.executes_at)}` : `#${o.id} si ${o.trigger_label} ${o.condition === "above" ? "\u2265" : "\u2264"} ${o.trigger_price}`).join(" \xB7 ")}`);
    }
  }
  const closed = listPositions(m.id).filter((p) => p.status === "closed");
  if (closed.length) {
    const wins = closed.filter((p) => (p.pnlUsd ?? 0) > 0).length;
    lines.push("", `Operaciones cerradas: ${closed.length} (${wins} con beneficio)`);
    for (const p of closed.slice(0, 4)) lines.push(`- ${p.symbol}: ${pct3(p.pnlPct ?? 0)} en ${p.heldMinutes} min (${p.exitReason ?? "venta"})`);
  }
  const recent = db.prepare("SELECT ts, kind, summary, reasoning FROM journal WHERE mission_id = ? AND kind NOT IN ('rejected') ORDER BY id DESC LIMIT 5").all(m.id);
  if (recent.length) {
    lines.push("", "\xDAltimos movimientos:");
    for (const j of recent) {
      const why = j.reasoning?.match(/^Por qué: (.*)$/m)?.[1];
      lines.push(`- ${hhmm3(j.ts)} ${j.summary}${why ? ` \xB7 ${why.slice(0, 120)}` : ""}`);
    }
  }
  const notes = db.prepare("SELECT ts, title FROM activity WHERE kind = 'thought' AND mission_id = ? ORDER BY id DESC LIMIT 2").all(m.id);
  if (notes.length) {
    lines.push("", "\xDAltima nota del agente:");
    for (const n3 of notes) lines.push(`- ${hhmm3(n3.ts)} ${n3.title.slice(0, 220)}`);
  }
  const review = db.prepare("SELECT ts, title, body FROM activity WHERE kind = 'review' AND mission_id = ? ORDER BY id DESC LIMIT 1").get(m.id);
  if (review) lines.push("", `Revisor (${hhmm3(review.ts)}): ${review.title}${review.body ? ` \xB7 ${review.body.slice(0, 200)}` : ""}`);
  const requests = listCapabilityRequests("open");
  if (requests.length) {
    lines.push("", `El agente pide (${requests.length}, rev\xEDsalas con /dementeking:peticiones):`);
    for (const r of requests.slice(0, 3)) lines.push(`- ${r.capability}${r.times_requested > 1 ? ` (${r.times_requested} veces)` : ""}`);
  }
  return lines.join("\n");
}

